ACTS.load26demo=()=>{if(!canPrep())return;ask("This loads the 2026 insurance, tax, overtime and proration values collected from public sources and marks them approved for TRIAL USE. Nobody has checked them against the official text. Payroll can be calculated and reviewed with them, but a run that uses them can never be finalized or paid until the rules are verified and approved properly.","Load for trial use",()=>{const eff="2026-01-01";let n=0;P26.forEach(([key,value,pSrc,pLaw],i)=>{let r=RULES().find(x=>x.key===key&&x.eff===eff&&!x.test&&x.status!=="approved");if(!r){if(RULES().some(x=>x.key===key&&x.eff===eff&&!x.test))return;r={id:"r"+Date.now()+i,key,value,eff,createdAt:iso(T0),pSrc,pLaw};RULES().push(r)}Object.assign(r,{value,status:"approved",demo:true,createdBy:r.createdBy||role,approvedBy:role,verifier:"Trial use (unverified)",verDate:iso(T0),srcUrl:pSrc,legalRef:pLaw});n++});sv("rules",false);audit("2026 rules loaded for trial use",n+" rule(s), unverified");toast(n?"2026 rules loaded for trial use.":"The 2026 rules already exist.");draw()})};
ACTS.rver=id=>{const r=RULES().find(x=>x.id===id);if(!r||!r.demo||!canPrep())return;r.status="review";r.demo=false;r.createdBy="Trial setup";sv("rules",false);audit("Trial rule sent for verification",r.key);toast("Sent for verification. HR Director or Finance Manager can now check and approve it.");draw()};
ACTS.load26=()=>{if(!canPrep())return;const eff="2026-01-01";let n=0;P26.forEach(([key,value,pSrc,pLaw],i)=>{if(RULES().some(r=>r.key===key&&r.eff===eff&&!r.test))return;RULES().push({id:"r"+Date.now()+i,key,value,eff,status:"draft",createdBy:role,createdAt:iso(T0),pSrc,pLaw});n++});sv("rules",false);audit("Proposed 2026 rules loaded as drafts",n+" rule(s), effective "+eff);toast(n?n+" draft rule(s) added. Submit them for review.":"The 2026 drafts already exist.");TAB.rl="hist";draw()};
