function pay_proc(){const runs=RUNS().slice().reverse(),can=canPrep(),pre=SELRUN.startsWith("new:")?SELRUN.slice(4):"";
 const free=monthsBack(8).filter(m=>!RUNS().some(r=>r.period===m.key&&r.kind==="regular"));
 const list=runs.map(r=>[esc(runLabel(r)),rsb(r.status),String(r.results.length),canSalV()?fmtC(tot(r,"net")):"Restricted",r.test?bd("Unverified rules","s-wn"):"",`<button class="b" data-act="selrun:${r.id}">Open</button>`]);
 const rrNow=resolveRules(iso(T0)),noRules=rrNow.rules?"":`<div class="notice er" role="alert"><b>Payroll rules are missing</b> for today: ${rrNow.missing.map(k=>esc(RKEYS.find(x=>x[0]===k)[1])).join(", ")}.<div class="bar" style="margin-top:8px">${can?`<button class="b p" data-act="load26demo">Load 2026 rules for trial use</button> `:""}<button class="b" data-go="comp">Open Tax &amp; Insurance Settings</button></div></div>`;
 const sel=RUNS().find(r=>r.id===SELRUN);
 return`${noRules}${can?`<div class="card"><form class="inl" data-form="runnew"><label>Period<select name="period">${free.map(m=>`<option value="${m.key}" ${m.key===pre?"selected":""}>${m.label}</option>`).join("")}</select></label><button class="b p" type="submit" ${free.length?"":"disabled"}>Create regular run</button></form><div class="err"></div></div>`:""}
 <div style="margin-top:12px">${tbl(["Run","Status","Employees","Net pay","",""],list,{empty:"No runs yet. Create one for a period above."})}</div>${sel?runDetail(sel):""}`}
FORMS.runnew=o=>{if(!canPrep()||!o.period)return"Choose a period.";if(RUNS().some(r=>r.period===o.period&&r.kind==="regular"))return"That period already has a regular run.";const id="N"+Date.now();RUNS().push({id,period:o.period,kind:"regular",status:"draft",results:[],exc:[],excl:{},hist:[{t:new Date().toISOString(),role,a:"Run created"}],createdBy:role});sv("runs");audit("Payroll run created",o.period);SELRUN=id;draw()};
