function runDetail(r){const can=canPrep(),s=r.status,sal=canSalV(),nb=r.exc.filter(x=>x.sev==="block"),V=varRows(r),needR=V.filter(v=>v.need&&!v.reason).length;
 const btn=[];
 if(can&&["draft","validation_required","under_review"].includes(s))btn.push(`<button class="b p" data-act="calc:${r.id}">${r.results.length?"Recalculate":"Calculate payroll"}</button>`);
 if(can&&s==="under_review")btn.push(`<button class="b p" data-act="submit:${r.id}">Submit for approval</button>`);
 if(role===R.FIN&&s==="approved")btn.push(`<button class="b p" data-act="fin:${r.id}">Finalize payroll</button>`);
 if([R.PAY,R.FIN].includes(role)&&s==="finalized")btn.push(`<button class="b p" data-act="paid:${r.id}">Mark as paid</button>`);
 if(can&&FINAL.includes(s)&&r.kind==="regular"&&!RUNS().some(x=>x.base===r.id))btn.push(`<button class="b" data-act="adj:${r.id}">Create adjustment run</button>`);
 if(can&&s==="draft")btn.push(`<button class="b" data-act="rundel:${r.id}">Delete run</button>`);
 const gates=[[!r.test,"Rules are verified and approved (not test or trial values)"],[!nb.length,"No unresolved blocking exceptions"],[needR===0,"Every large variance has a reason"],[(perOf(r.period)||{}).fullEnd<iso(T0),"Period has ended"]];
 const RD=(t,k)=>()=>({title:t+": "+runLabel(r),desc:"Per employee, from this payroll run.",cols:["No.","Name","Department",k==="net"&&t.startsWith("Emp")?"Net pay":t],rows:r.results.map(x=>[x.no,x.name,x.dept||"",fmtC(x[k])])});
 return`${secH(esc(runLabel(r)),rsb(s))}<div class="bar">${btn.join(" ")}</div>
 ${r.results.length&&sal?`<div class="grid kpis" style="margin-top:12px">${stat("Employees",r.results.length,"",RD("Employees in this run","net"))}${stat("Gross pay",fmtC(tot(r,"gross")),"",RD("Gross pay","gross"))}${stat("Employee insurance",fmtC(tot(r,"empIns")),"",RD("Employee insurance","empIns"))}${stat("Income tax",fmtC(tot(r,"tax")),"",RD("Income tax","tax"))}${stat("Net pay",fmtC(tot(r,"net")),"",RD("Net pay","net"))}${stat("Employer cost",fmtC(tot(r,"cost")),"Gross plus employer insurance",RD("Employer cost","cost"))}</div>`:""}
 <div class="card" style="margin-top:12px"><h2>Checks before finalizing</h2><ul class="chk">${gates.map(g=>`<li>${g[0]?bd("Pass","s-ok"):bd("Open","s-er")} ${g[1]}</li>`).join("")}</ul>${r.test?note("This run used illustrative TEST rules. It can be reviewed but never finalized.","sm"):""}</div>
 ${r.exc.length?`${secH("Validation exceptions")}${tbl(["Employee","Issue","Severity",""],r.exc.map(x=>[esc(x.no+" "+((empBy(x.no)||{}).name||"")),esc(x.msg),x.sev==="block"?bd("Blocks","s-er"):bd("Warning","s-wn"),x.sev==="block"&&can&&["validation_required","under_review"].includes(s)?`<button class="b" data-act="excl:${r.id}|${x.no}">Exclude from run</button>`:""]))}`:""}
 ${Object.keys(r.excl||{}).length?note("Excluded from this run: "+Object.entries(r.excl).map(([n,t])=>esc(n+" ("+t+")")).join(", "),"sm"):""}
 ${r.results.length&&sal?`${secH("Results")}${ptbl("res"+r.id,["Employee","Department","Days","Overtime","Gross","Insurance","Tax","Net","Employer cost"],r.results.map(x=>[esc(x.name)+` <span class="mu">${x.no}</span>`,esc(x.dept),(x.wd||"")+(x.md?"/"+x.md:""),fmtC(x.ot||0),fmtC(x.gross),fmtC(x.empIns),fmtC(x.tax),fmtC(x.net)+(x.dnet!=null?` <span class="mu">(${x.dnet>=0?"+":""}${fmtC(x.dnet)})</span>`:""),fmtC(x.cost)]),{csv:"res"+r.id})}`:""}
 ${secH("History")}${tbl(["Time","Role","Event"],r.hist.slice().reverse().map(h=>[h.t.slice(0,16).replace("T"," "),esc(h.role),esc(h.a)]))}${note("Included: proration for joiners and leavers, approved overtime and payroll inputs, when their rules are approved. Not included yet: final settlement, year-to-date tax reconciliation and retroactive salary changes. Tax and insurance are worked out on each month alone.")}`}
ACTS.calc=id=>{const r=RUNS().find(x=>x.id===id);if(!r||!canPrep()||!["draft","validation_required","under_review"].includes(r.status))return;const er=calcRun(r);if(er){toast(er);$("#view").insertAdjacentHTML("afterbegin",`<div class="notice er" role="alert">${esc(er)}</div>`);return}sv("runs");audit("Payroll calculated",runLabel(r)+(r.test?" (test rules)":""));toast("Payroll calculated");draw()};
