function runPick(key,filter){const L=RUNS().filter(filter);if(!L.length)return null;if(!L.some(r=>r.id===TAB[key]))TAB[key]=L[L.length-1].id;return{L,r:L.find(r=>r.id===TAB[key])}}
const runSel=(key,L)=>`<div class="bar"><label>Run <select id="rsel_${key}" data-sel="${key}">${L.map(r=>`<option value="${r.id}" ${r.id===TAB[key]?"selected":""}>${esc(runLabel(r))} · ${RS[r.status]}</option>`).join("")}</select></label></div>`;
