const slipRows=x=>{const r=[["Basic salary"+(x.pf&&x.pf<1?" ("+x.wd+" of "+x.md+" days)":""),x.basic],["Allowances",x.allow]];if(x.ot)r.push(["Overtime ("+x.otH+" h)",x.ot]);if(x.inp)r.push(["Bonus and other earnings",x.inp]);return r};
function slipText(r,x){const p=perOf(r.period)||{label:r.period};return["SMR payslip - "+p.label,x.name+" ("+x.no+"), "+x.dept,...slipRows(x).map(l=>l[0]+": "+fmtC(l[1])),"Gross: "+fmtC(x.gross),"Employee insurance: -"+fmtC(x.empIns),"Income tax: -"+fmtC(x.tax),...(x.ded?["Other deductions: -"+fmtC(x.ded)]:[]),"Net pay: "+fmtC(x.net)].join("\n")}
function slipHtml(r,x){const p=perOf(r.period)||{label:r.period};return`<div class="slip"><div class="bar"><b>${p.label}</b>${rsb(r.status)}</div><div class="mu">${esc(x.name)} · ${x.no} · ${esc(x.dept)}</div>${x.md?`<div class="mu" style="margin-top:4px">Worked days: ${x.wd} of ${x.md}</div>`:""}${tbl(["Earnings","Amount"],[...slipRows(x).map(l=>[l[0],fmtC(l[1])]),["<b>Gross</b>","<b>"+fmtC(x.gross)+"</b>"]])}<div style="height:8px"></div>${tbl(["Deductions","Amount"],[["Employee insurance",fmtC(x.empIns)],["Income tax",fmtC(x.tax)],...(x.ded?[["Other deductions",fmtC(x.ded)]]:[])])}<div class="card" style="margin-top:8px"><b>Net pay ${fmtC(x.net)}</b></div><button class="b" style="margin-top:10px" data-act="slipcopy:${r.id}|${x.no}">Copy as text</button></div>`}
function payslips(){const emp=role===R.EMP,p=runPick("ps",r=>FINAL.includes(r.status));if(!p)return forbid("No payslips yet. They appear once a payroll is finalized.");const r=p.r;
 if(emp){const x=r.results.find(y=>y.no===WSNO);return`${runSel("ps",p.L)}${x?slipHtml(r,x):'<div class="card"><div class="empty">You are not in this payroll run.</div></div>'}${note("Select the employee in My Workspace to preview another person's payslip.")}`}
 return`${runSel("ps",p.L)}<div style="margin-top:10px">${ptbl("ps",["Employee","No.","Department","Net pay",""],r.results.filter(x=>inScope(empBy(x.no)||{})).map(x=>[esc(x.name),x.no,esc(x.dept),fmtC(x.net),`<button class="b" data-act="slip:${r.id}|${x.no}">View payslip</button>`]),{csv:"psl"})}</div>${note("Payslips are available only for finalized payroll.")}`}
ACTS.slip=a=>{const[id,no]=a.split("|"),r=RUNS().find(x=>x.id===id),x=r&&r.results.find(y=>y.no===no);if(!x||!FINAL.includes(r.status)||!canSee("payslips"))return;if(role===R.EMP&&no!==WSNO)return;$("#dt").textContent="Payslip";$("#dd").textContent=x.name;$("#db").innerHTML=slipHtml(r,x);$("#dx").hidden=true;$("#drawer").classList.add("open");audit("Payslip viewed",no+" "+r.period)};
