function runsFor(no){return RUNS().filter(r=>FINAL.includes(r.status)).map(run=>({run,res:run.results.find(x=>x.no===no)})).filter(x=>x.res)}

/* ----- variance, reconciliation, settlements ----- */
const VTH=()=>db("vth",{pct:10},false).pct;
function prevRun(r){const ms=monthsBack(9),i=ms.findIndex(m=>m.key===r.period);const pk=ms[i+1]&&ms[i+1].key;return RUNS().filter(x=>x.period===pk&&x.results.length).sort((a,b)=>FINAL.includes(a.status)?-1:1)[0]}
function varRows(r){const pr=prevRun(r),R2=db("varr",{},false);if(!pr)return[];const th=VTH(),o=[];
 r.results.forEach(x=>{const y=pr.results.find(z=>z.no===x.no);if(!y){o.push({no:x.no,name:x.name,prev:0,cur:x.net,d:x.net,pct:100,need:true,why:"New in this run",reason:R2[r.id+"|"+x.no]});return}
  const d=x.net-y.net,pct=y.net?d/y.net*100:100;if(Math.abs(pct)>=th)o.push({no:x.no,name:x.name,prev:y.net,cur:x.net,d,pct,need:true,why:"Net pay changed by "+pct.toFixed(1)+" %",reason:R2[r.id+"|"+x.no]})});
 pr.results.forEach(y=>{if(!r.results.some(x=>x.no===y.no))o.push({no:y.no,name:y.name,prev:y.net,cur:0,d:-y.net,pct:-100,need:true,why:"Not in this run",reason:R2[r.id+"|"+y.no]})});return o}
function pay_var(){if(!canSalV())return forbid("Salary data is restricted for your role.");const p=runPick("pv",r=>r.results.length);if(!p)return forbid("No calculated payroll yet.");const r=p.r,V=varRows(r),pr=prevRun(r),can=canPrep()&&["draft","validation_required","under_review"].includes(r.status);
 const PN=(x,t)=>({title:t+": "+runLabel(x),desc:"Net pay per employee.",cols:["No.","Name","Department","Net pay"],rows:x.results.map(y=>[y.no,y.name,y.dept||"",fmtC(y.net)])}),VD=(t,f)=>({title:t,desc:"Compared with "+(pr?runLabel(pr):"the previous run")+". Changes at or above the threshold are flagged.",cols:["No.","Name","Previous net","Current net","Change","Why flagged","Reason"],rows:V.filter(f).map(v=>[v.no,v.name,fmtC(v.prev),fmtC(v.cur),fmtC(v.d),v.why,v.reason||"Missing"])});
 return`${runSel("pv",p.L)}${pr?`<div class="grid kpis" style="margin-top:10px">${stat("Previous run net",fmtC(tot(pr,"net")),esc(runLabel(pr)),()=>PN(pr,"Previous run net"))}${stat("This run net",fmtC(tot(r,"net")),"",()=>PN(r,"This run net"))}${stat("Change",fmtC(tot(r,"net")-tot(pr,"net")),"",()=>VD("Employees whose net pay changed",()=>true))}${stat("Items to explain",V.filter(v=>!v.reason).length,"Reason needed before submitting",()=>VD("Items that still need a reason",v=>!v.reason))}</div>`:note("There is no earlier run to compare with.")}
 ${pr?`<div style="margin-top:12px">${tbl(["Employee","Previous net","Current net","Change","Why flagged","Reason"],V.map(v=>[esc(v.name)+` <span class="mu">${v.no}</span>`,fmtC(v.prev),fmtC(v.cur),fmtC(v.d),esc(v.why),v.reason?esc(v.reason):can?`<button class="b" data-act="vr:${r.id}|${v.no}">Add reason</button>`:bd("Missing","s-er")]),{empty:"No change above the threshold."})}</div>`:""}
 ${canPrep()?`<div class="card" style="margin-top:12px"><form class="inl" data-form="vth"><label>Flag changes of at least (%)<input type="number" name="pct" min="1" max="100" value="${VTH()}"></label><button class="b" type="submit">Save threshold</button></form><div class="err"></div></div>`:""}`}
ACTS.vr=a=>{const[id,no]=a.split("|");ask("Why did the net pay change for "+no+"?","Save reason",(t)=>{db("varr",{},false)[id+"|"+no]=t;sv("varr",false);audit("Variance explained",no+": "+t);draw()},{reason:1})};
FORMS.vth=o=>{const n=+o.pct;if(!(n>=1&&n<=100))return"Enter 1 to 100.";db("vth",{pct:10},false).pct=n;sv("vth",false);audit("Variance threshold changed",n+" %");draw()};
reg("pay_var","Payroll Variance Analysis","Net pay changes against the previous month, with a reason required for large ones.",A("PAY","FIN","HRD"),pay_var);
function pay_rec(){if(!canSalV())return forbid("Salary data is restricted for your role.");const p=runPick("pr",r=>FINAL.includes(r.status));if(!p)return forbid("Reconciliation starts after payroll is finalized.");const r=p.r,net=tot(r,"net");
 const jr=[["Salaries expense (debit)",fmtC(tot(r,"gross"))],["Employer insurance expense (debit)",fmtC(tot(r,"erIns"))],["Net salaries payable (credit)",fmtC(net)],["Employee insurance payable (credit)",fmtC(tot(r,"empIns"))],["Employer insurance payable (credit)",fmtC(tot(r,"erIns"))],["Income tax payable (credit)",fmtC(tot(r,"tax"))]];
 const pay=r.results.map(x=>{const e=empBy(x.no)||{};return[x.no,esc(x.name),(x.net/100).toFixed(2),esc(e.bankname||"Missing"),esc(e.bankholder||x.name),esc(e.iban||e.bankacct||"Missing")]});
 return`${runSel("pr",p.L)}${rsb(r.status)} ${attBtn("recon|"+r.id,"Bank statement: "+runLabel(r),"Bank statement")}
 <div class="grid kpis" style="margin-top:10px">${stat("Payroll net pay",fmtC(net),"",()=>({title:"Payroll net pay",desc:"What each employee is due. Total "+fmtC(net)+".",cols:["No.","Name","Net pay"],rows:r.results.map(x=>[x.no,x.name,(x.net/100).toFixed(2)])}))}${stat("Bank paid",r.bank!=null?fmtC(r.bank):"Not entered","",()=>({title:"Bank paid",desc:r.bank!=null?"Total entered from the bank statement: "+fmtC(r.bank)+".":"Not entered yet. Enter the total paid per the bank statement after the payment is made.",cols:[],rows:[]}))}${stat("Difference",r.bank!=null?fmtC(r.bank-net):"–","",()=>({title:"Difference",desc:r.bank!=null?(r.bank===net?"The bank total matches payroll.":"The bank total differs from payroll by "+fmtC(r.bank-net)+(r.recWhy?". Reason: "+r.recWhy:". A reason is required to reconcile.")):"Appears after the bank total is entered.",cols:[],rows:[]}))}</div>
 ${r.status==="reconciliation_required"&&[R.PAY,R.FIN].includes(role)?`<div class="card" style="margin-top:12px"><form class="g" data-form="recon"><input type="hidden" name="id" value="${r.id}">${fld("Total paid per bank statement (EGP)","bank","number",{req:1,step:"0.01",min:0})}${fld("Reason if different","why","text")}<button class="b p" type="submit">Reconcile</button></form><div class="err"></div></div>`:r.status==="reconciled"?note("Reconciled on "+esc(r.recAt)+(r.recWhy?". Reason for difference: "+esc(r.recWhy):". Matches payroll.")):""}
 ${secH("Journal summary",csvBtn("jr",["Account","Amount"],jr))}${tbl(["Account","Amount"],jr)}${note("Account codes are not configured. Map these lines to your chart of accounts before posting.")}
 ${secH("Payment file",csvBtn("pf",["No.","Name","Net pay (EGP)","Bank","Account holder","IBAN / account"],pay))}${note("The file lists amounts to pay. Real bank details need secure storage on a backend, so none are held here.")}`}
FORMS.recon=o=>{const r=RUNS().find(x=>x.id===o.id);if(!r||r.status!=="reconciliation_required"||![R.PAY,R.FIN].includes(role))return"Not allowed.";const b=C(o.bank),net=tot(r,"net");if(b!==net&&!o.why.trim())return"The amount differs from payroll by "+fmtC(b-net)+". Enter the reason.";
 r.bank=b;r.recWhy=b!==net?o.why.trim():"";r.recAt=iso(T0);r.status="reconciled";r.hist.push({t:new Date().toISOString(),role,a:"Reconciled"+(r.recWhy?" with difference: "+r.recWhy:"")});sv("runs");audit("Payroll reconciled",runLabel(r)+(r.recWhy?" difference "+fmtC(b-net):""));toast("Payroll reconciled");draw()};
reg("pay_rec","Payroll Reconciliation","Compare payroll to the bank, then export the journal and payment list.",A("PAY","FIN","HRD"),pay_rec);
function pay_fs(){const L=allEmps().filter(e=>e.status==="Terminated"&&inScope(e)),A2=(SAMPLE.assets||{});
 return`${note("<b>Final settlement calculation is blocked.</b> End-of-service and leave encashment rules have not been entered or verified, and this system will not calculate a settlement without them. The checklist below tracks what can be checked today.","sm")}${tbl(["Employee","Department","Last day","Assets to return","Settlement"],L.map(e=>[esc(e.name)+` <span class="mu">${e.no}</span>`,esc(e.dept),e.term||e.end||"–",MODE==="sample"&&(A2[e.no]||[]).length?bd((A2[e.no]).length+" item(s)","s-wn"):bd("None recorded","s-mu"),bd("Blocked: rules not approved","s-er")]),{empty:"No leavers to settle."})}`}
reg("pay_fs","Final Settlements","Leavers awaiting settlement. Calculation stays blocked until the legal rules are approved.",A("HRD","PAY","FIN"),pay_fs);

/* ----- payroll dashboard ----- */
function paydash(){const runs=RUNS(),ms=monthsBack(6).slice().reverse(),sal=canSalV();if(!sal)return forbid("Salary data is restricted for your role.");
 const last=runs.filter(r=>r.results.length).sort((a,b)=>a.period<b.period?1:-1)[0],rr=resolveRules(iso(T0)),pend=runs.filter(r=>r.status==="pending_approval").length,open=runs.reduce((s,r)=>s+r.exc.filter(x=>x.sev==="block").length,0);
 const PDL=(t,f)=>()=>({title:t,desc:"Payroll runs.",cols:["Run","Period","Status","Employees"],rows:runs.filter(f).map(r=>[runLabel(r),r.period,RS[r.status],String(r.results.length)])}),PDR=(x,t,k)=>({title:t+": "+runLabel(x),desc:"Per employee.",cols:["No.","Name","Department",t],rows:x.results.map(y=>[y.no,y.name,y.dept||"",fmtC(y[k])])});
 const bars=ms.map(m=>{const r=runs.find(x=>x.period===m.key&&x.kind==="regular"&&x.results.length);return{l:m.label.split(" ")[0].slice(0,3),v:r?tot(r,"net"):0}}),mx=Math.max(1,...bars.map(b=>b.v));
 return`<div class="grid kpis">${stat("Latest run",last?esc(runLabel(last)):"None",last?RS[last.status]:"Create one in Payroll Processing",PDL("All payroll runs",()=>true),"pay_proc")}${stat("Net pay",last?fmtC(tot(last,"net")):"–","",last?()=>PDR(last,"Net pay","net"):null)}${stat("Employer cost",last?fmtC(tot(last,"cost")):"–","",last?()=>PDR(last,"Employer cost","cost"):null)}${stat("Awaiting approval",pend,"",PDL("Runs awaiting approval",r=>r.status==="pending_approval"),"pay_proc")}${stat("Blocking exceptions",open,"",()=>({title:"Blocking exceptions",desc:"Problems that stop a run from being finalized.",cols:["Run","No.","Name","Problem"],rows:runs.flatMap(r=>r.exc.filter(x=>x.sev==="block").map(x=>[runLabel(r),x.no,(empBy(x.no)||{}).name||"",x.msg]))}),"pay_proc")}${stat("Rules",rr.rules?(rr.unver?"Test values":"Approved"):"Incomplete",rr.rules?"":rr.missing.length+" rule(s) missing",()=>({title:"Tax and insurance rules",desc:"Value in force for today.",cols:["Rule","Status"],rows:RKEYS.map(([k,l])=>[l,rr.missing&&rr.missing.includes(k)?"Missing":rr.unver?"Test value":"Approved"])}),"comp")}</div>
 <div class="card" style="margin-top:14px"><h2>Net pay by month</h2><div class="hbars">${bars.map(b=>`<div class="hbr"><span>${b.l}</span><i style="width:${b.v/mx*100}%"></i><b>${b.v?fmtC(b.v):"No run"}</b></div>`).join("")}</div></div>
 <div class="card" style="margin-top:14px"><h2>Pipeline</h2>${tbl(["Status","Runs"],Object.keys(RS).map(s=>[RS[s],runs.filter(r=>r.status===s).length]))}</div>`}
reg("paydash","Payroll Dashboard","Where payroll stands: latest run, approvals, exceptions and rules.",A("PAY","FIN","HRD"),paydash);

/* ----- payroll inputs (Odoo other inputs) ----- */
const monthsFwd=n=>{const o=[];for(let i=1;i<=n;i++){const d=new Date(T0.getFullYear(),T0.getMonth()+i,1);o.push({key:iso(d).slice(0,7),label:d.toLocaleString("en",{month:"long",year:"numeric"})})}return o};
const INTYPES=["Variable allowance","Bonus","One-off allowance","Deduction","Loan installment","Salary advance"];
function pay_inputs(){const can=canPrep(),L=db("pinp",[]).filter(x=>x.mode===MODE),ms=monthsBack(8);
 const locked=pk=>RUNS().some(r=>r.period===pk&&FINAL.includes(r.status));
 const rows=L.slice().reverse().map(x=>{const e=empBy(x.no);return[esc(e?e.name:x.no),x.no,(perOf(x.period)||{label:x.period}).label+(x.until?" to "+x.until:""),x.type,fmtC(Math.round(x.amount*100))+(x.until?" / month":""),esc(x.note||""),can&&!locked(x.period)?`<button class="b" data-act="pi_del:${x.id}">Delete</button>`:bd("Locked","s-mu")]});
 return`${note("Inputs are amounts for one payroll month, or for every month until the end month you choose (variable allowances such as shift or site allowance). Bonus and one-off allowance are added to gross (taxable and insurable flags come from the Bonus component in Salary Components). Deduction, loan installment and salary advance are taken from net pay after tax. Recalculate the run after adding inputs.","sm")}
 ${can?`<div class="card" style="margin-top:10px"><h2>Add input</h2><form class="g" data-form="pinew">${fld("Employee","no","select",{req:1,opts:ALLE().filter(e=>e.status!=="Terminated").map(e=>[e.no,e.name+" ("+e.no+")"])})}${fld("Payroll month","period","select",{req:1,opts:ms.filter(m=>!locked(m.key)).map(m=>[m.key,m.label])})}${fld("Type","type","select",{opts:INTYPES,val:"Bonus"})}${fld("Amount (EGP)","amount","number",{req:1,min:0.01,step:"0.01"})}${fld("Repeat every month until (optional)","until","select",{opts:[["","Only this month"],...ms.map(m=>[m.key,m.label]),...monthsFwd(6).map(m=>[m.key,m.label])]})}${fld("Note","note","text")}<button class="b p" type="submit">Add</button></form><div class="err"></div></div>`:""}
 <div style="margin-top:10px">${ptbl("pi",["Employee","No.","Month","Type","Amount","Note",""],rows,{csv:"pi",empty:"No inputs yet."})}</div>`}
FORMS.pinew=o=>{if(!canPrep())return"Not allowed.";const a=+o.amount;if(!(a>0))return"Enter an amount above zero.";if(o.until&&o.until<o.period)return"The end month cannot be before the start month.";if(RUNS().some(r=>r.period===o.period&&FINAL.includes(r.status)))return"That month is already finalized.";db("pinp",[]).push({id:"i"+Date.now(),mode:MODE,no:o.no,period:o.period,type:o.type,amount:a,until:o.until||"",note:(o.note||"").trim(),by:role});sv("pinp");audit("Payroll input added",o.no+" "+o.type+" "+fmtC(Math.round(a*100))+" for "+o.period);toast("Added. Recalculate the run to include it.");draw()};
ACTS.pi_del=id=>ask("Delete this input?","Delete",()=>{const L=db("pinp",[]),i=L.findIndex(x=>x.id===id);if(i<0||!canPrep())return;audit("Payroll input deleted",L[i].no+" "+L[i].type);L.splice(i,1);sv("pinp");draw()});
reg("pay_inputs","Payroll Inputs","Bonuses, one-off allowances, deductions, loans and advances for a payroll month.",A("PAY","HRD","FIN"),pay_inputs);
